def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in into s_out."""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where strings differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length
        if len(s_in) == len(s_out):
            return "", "", -1  # No change needed
        elif len(s_in) > len(s_out):
            # Deletion at end
            return s_in[len(s_out):], "", len(s_out)
        else:
            # Insertion at end  
            return "", s_out[len(s_in):], len(s_in)

    # Find what to replace at this position
    # Check if we can match a substring
    old_sub = ""
    new_sub = ""

    # Try to find matching patterns
    for i in range(pos, min(len(s_in), len(s_out)) + 1):
        if s_in[pos:i+1] == s_out[pos:i+1]:
            continue
        else:
            old_sub = s_in[pos:i]
            new_sub = s_out[pos:pos+len(old_sub)]
            break

    # If we couldn't determine it properly, simpler approach:
    if old_sub == "":
        old_sub = s_in[pos:pos+1]
        new_sub = s_out[pos:pos+1]

    return old_sub, new_sub, pos

